parameters.jsCode:
const response = $input.first().json;
let rawText = '';

try {
  rawText = response.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Falha ao extrair texto da resposta do Gemini: ' + JSON.stringify(response));
}

// Limpa marcações markdown se presentes
rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
const parsed = JSON.parse(rawText);

const context = $('Normalizar Variáveis').first().json;
const crmBaseUrl = context.crmBaseUrl || 'https://blacklink-crm.netlify.app';
const totalSlides = parsed.slides ? parsed.slides.length : 1;

// Monta URLs dinâmicas do renderizador server-side do Black Link
const slidesComImagens = (parsed.slides || []).map((slide, index) => {
  const slideNum = slide.slideNumber || index + 1;
  const query = new URLSearchParams({
    slide: String(slideNum),
    total: String(totalSlides),
    headline: slide.headline || '',
    body: slide.bodyText || '',
    format: context.format || 'carousel'
  });
  const imageUrl = `${crmBaseUrl}/api/marketing/render-slide?${query.toString()}`;
  return {
    ...slide,
    slideNumber: slideNum,
    imageUrl
  };
});

return {
  id: `cr-n8n-${Date.now()}`,
  theme: context.theme,
  format: context.format,
  targetAudience: context.targetAudience,
  hookHeadline: parsed.hookHeadline,
  bodyCopy: parsed.bodyCopy,
  ctaText: parsed.ctaText,
  hashtags: parsed.hashtags || ['#VendasB2B', '#BlackLink'],
  slides: slidesComImagens,
  imageUrls: slidesComImagens.map(s => s.imageUrl),
  publishToInstagram: context.publishToInstagram,
  createdAt: new Date().toISOString(),
  source: 'n8n'
};
